TOOLS = {'iniconfig': '2.3.1', 'jsonschema': '4.26.0', 'jsonschema-path': '0.5.0', 'jsonschema-specifications': '2025.9.1', 'lazy-object-proxy': '1.13.0', 'openapi-schema-validator': '0.9.0', 'openapi-spec-validator': '0.9.0', 'pathable': '0.6.0', 'pluggy': '1.7.0', 'pygments': '2.21.0', 'pytest': '9.2.0', 'pytest-asyncio': '1.4.1', 'referencing': '0.37.0', 'rfc3339-validator': '0.1.4', 'rpds-py': '2026.9.1', 'six': '1.17.0'}

def tree_digest(path, *, count, exclude_self=False):
    entries = list(path.rglob("*"))
    if path.is_symlink() or len(entries) > 2 * MAX_FILES or any(p.is_symlink() for p in entries):
        refuse("source symlinks/count differ from approval")
    files = sorted(p for p in entries if "__pycache__" not in p.parts and p.is_file()
                   and not (exclude_self and p == Path(__file__).resolve()))
    if (len(files) != count or len(files) > MAX_FILES
            or any(p.stat().st_size > MAX_BLOB for p in files)
            or sum(p.stat().st_size for p in files) > MAX_TREE
            or any(not stat.S_ISREG(p.stat().st_mode) for p in files)):
        refuse("frozen source count/bytes/type differ")
    manifest = [[str(p.relative_to(SERVER)), hashlib.sha256(p.read_bytes()).hexdigest()] for p in files]
    return hashlib.sha256(json.dumps(manifest, separators=(",", ":")).encode()).hexdigest()

def private_empty(value):
    path = Path(value)
    if (not path.is_absolute() or ".." in path.parts or not path.is_dir()
            or any(p.is_symlink() for p in [path, *path.parents])
            or path.stat().st_uid != os.getuid() or path.stat().st_mode & 0o077
            or "test" not in path.name.lower() or any(path.iterdir())):
        refuse("four separate private owned empty test directories required")
    return path

def inventory():
    if not SITE.is_dir() or SITE.is_symlink() or not CANDIDATE.is_dir():
        refuse()
    cfg = (CANDIDATE / "pyvenv.cfg").read_text()
    if not re.search(r"^include-system-site-packages\s*=\s*false\s*$", cfg, re.M):
        refuse()
    if any(p.is_symlink() or p.suffix == ".pth" or p.name in {"sitecustomize.py", "usercustomize.py"}
           for p in SITE.rglob("*")):
        refuse()
    installed = {}
    for dist in importlib.metadata.distributions(path=[str(SITE)]):
        name = re.sub(r"[-_.]+", "-", dist.metadata["Name"]).lower()
        if name in installed:
            refuse()
        installed[name] = dist.version
    if len(RUNTIME) != 61 or len(TOOLS) != 16 or set(RUNTIME) & set(TOOLS) or installed != {**RUNTIME, **TOOLS}:
        refuse()
    return installed

def scratch_bound(root, anchor):
    now = root.lstat()
    identity = lambda s: (s.st_dev, s.st_ino, s.st_uid)
    if identity(now) != anchor or not stat.S_ISDIR(now.st_mode) or now.st_mode & 0o077:
        refuse()
    size = count = 0
    for path in root.rglob("*"):
        count += 1
        try:
            info = path.lstat()
        except FileNotFoundError:
            # Only transient descendants under the unchanged owned root may vanish.
            if not path.is_relative_to(root) or path == root:
                refuse()
            continue
        if stat.S_ISREG(info.st_mode):
            size += info.st_size
        if count > 4096 or size > LIMIT_SCRATCH:
            refuse()
    if identity(root.lstat()) != anchor:
        refuse()
    return size


def sources_unchanged():
    return (hashlib.sha256(FRONTEND.read_bytes()).hexdigest() == FRONTEND_SHA256
        and tree_digest(SERVER / "app", count=APP_COUNT) == APP_DIGEST
        and tree_digest(SERVER / "tests", count=TESTS_COUNT_WITHOUT_SELF, exclude_self=True) == TESTS_DIGEST
        and tree_digest(SERVER / "schema_migrations", count=SCHEMA_COUNT) == SCHEMA_DIGEST
        and hashlib.sha256(Path(__file__).read_bytes()).hexdigest() == os.environ["CAPABILITY_PRIVACY_RUNNER_SHA256"]
        and all(hashlib.sha256((SERVER / p).read_bytes()).hexdigest() == h for p,h in SUPPORT_FILES.items())
        and all(hashlib.sha256((SITE / p).read_bytes()).hexdigest() == h for p,h in DEPENDENCY_FILES.items()))


def verify_approval():
    if sys.argv[1:] != ["--execute-approved-capability-privacy-profile-tests"]: refuse("ROOT argument required")
    if (sys.version_info[:3] != (3,13,7) or sys.flags.optimize or not sys.flags.isolated
        or not sys.flags.no_site or not sys.dont_write_bytecode
        or os.confstr("CS_GNU_LIBC_VERSION") != "glibc 2.36"
        or Path(sys.executable).absolute().parent != CANDIDATE / "bin"
        or any("site-packages" in p or p in {"",str(SERVER)} for p in sys.path)
        or any(m in sys.modules for m in ("app","pytest","site"))): refuse("exact isolated candidate77 required")
    flags=("ROOT_APPROVED_CAPABILITY_PRIVACY_PROFILE_TESTS","RUN_PROTOCOL_PRIVACY_TESTS",
           "RUN_CAPABILITY_PRIVACY_PROFILE_TESTS",
           "PYTEST_DISABLE_PLUGIN_AUTOLOAD","PYTHONDONTWRITEBYTECODE")
    allowed={*flags,"HOME","PATH","LANG","LC_ALL","TMPDIR","UPLOAD_DIR",
             "CAPABILITY_PRIVACY_EMPTY_CWD","CAPABILITY_PRIVACY_EVIDENCE_DIR","CAPABILITY_PRIVACY_SCRATCH_DIR",
             "CAPABILITY_PRIVACY_RUNNER_SHA256"}
    if set(os.environ)-allowed or any(os.environ.get(f)!="1" for f in flags): refuse("clean explicit environment required")
    if os.environ.get("HOME")!=pwd.getpwuid(os.getuid()).pw_dir: refuse("actual HOME required")
    h=os.environ.get("CAPABILITY_PRIVACY_RUNNER_SHA256","")
    if not re.fullmatch(r"[0-9a-f]{64}",h) or hashlib.sha256(Path(__file__).read_bytes()).hexdigest()!=h: refuse("exact reviewed runner required")
    empty=private_empty(os.environ.get("CAPABILITY_PRIVACY_EMPTY_CWD",""))
    scratch=private_empty(os.environ.get("CAPABILITY_PRIVACY_SCRATCH_DIR",""))
    upload=private_empty(os.environ.get("UPLOAD_DIR",""))
    evidence=private_empty(os.environ.get("CAPABILITY_PRIVACY_EVIDENCE_DIR",""))
    roots=[p.resolve() for p in (empty,scratch,upload,evidence)]
    if (Path.cwd()!=empty or os.environ.get("TMPDIR")!=str(scratch) or len(set(roots))!=4
        or any(a!=b and (a.is_relative_to(b) or b.is_relative_to(a)) for a in roots for b in roots)
        or any(p.is_relative_to(SERVER/"app") or p.is_relative_to(SERVER/"tests") or p.is_relative_to(SERVER/"schema_migrations") for p in roots)):
        refuse("four distinct private roots required")
    if any(os.statvfs(p).f_bavail * os.statvfs(p).f_frsize < 8 * 1024**3 + 80 * 1024**2 for p in roots):
        refuse("offline free disk8GiB plus80MiB planning required")
    if not sources_unchanged(): refuse("full source/support/dependency pins differ")
    os.umask(0o077)
    return roots,inventory()


class OfflineBoundary:
    """All denied attempts remain recorded; controlled attempts are never counted as successes."""
    APP_MODULES={"app","app.api_access_logging","app.services","app.services.export_files"}
    SQL_MODULES={"asyncpg","sqlalchemy","psycopg","psycopg2","sqlite3","duckdb"}
    def __init__(self,writable):
        self.writable=writable
        self.denied=[]
        self.active_control=None
        self.controls={}
        self.probes_restored=False

    def deny(self,label):
        if len(self.denied)>=MAX_CAPTURE_EVENTS: refuse("denial capture cap")
        self.denied.append({"event":label,"control":self.active_control})
        refuse("offline action denied: "+label)

    def audit(self,event,args):
        if event.startswith("socket."): self.deny(event)
        if event in {"subprocess.Popen","os.system","os.posix_spawn","os.exec","os.fork","os.forkpty"}: self.deny(event)
        if event in {"os.putenv","os.unsetenv"}:
            key=os.fsdecode(args[0])
            # Exact pytest bookkeeping; no domain/settings environment mutations.
            if key not in {"PYTEST_CURRENT_TEST","PYTEST_VERSION"}: self.deny("environment-mutation")
        if event=="import":
            name=args[0]
            if name.split(".")[0] in self.SQL_MODULES:self.deny("sql-import")
            if name=="app" or name.startswith("app."):
                if name not in self.APP_MODULES:self.deny("application-import")
        if event=="open" and isinstance(args[0],(str,bytes,os.PathLike)):
            p=Path(os.fsdecode(args[0]))
            if p.name==".env" or p.name.startswith(".env.") or {".ssh",".vault",".claude"}&set(p.parts):self.deny("secret-file")
            flags=args[2] if len(args)>2 and isinstance(args[2],int) else 0
            if flags & (os.O_WRONLY|os.O_RDWR|os.O_CREAT|os.O_TRUNC|os.O_APPEND):
                absolute=p.resolve()
                if not any(absolute.is_relative_to(r) for r in self.writable):self.deny("outside-write")
        if event in {"os.remove","os.rmdir","os.mkdir","os.rename","os.chmod","os.chown","os.truncate","os.symlink","os.link"}:
            # New files and openpyxl temporary cleanup are confined to owned roots.
            for value in args[:2] if event in {"os.rename","os.link","os.symlink"} else args[:1]:
                if isinstance(value,(str,bytes,os.PathLike)):
                    p=Path(os.fsdecode(value)).resolve()
                    if not any(p.is_relative_to(r) for r in self.writable):self.deny("outside-filesystem-mutation")

    def install(self):
        sys.addaudithook(self.audit)
        old=socket.has_ipv6
        try:
            socket.has_ipv6=False
            import aiohttp
            import aiosmtplib
            import httpx
            import pywebpush
            import requests
        finally:socket.has_ipv6=old
        self.probes_restored=socket.has_ipv6 is old

    def denial_control(self,label):
        expected={"socket":"socket.__new__","dns":"socket.getaddrinfo","process":"subprocess.Popen",
                  "env":"environment-mutation","secret-file":"secret-file","outside-write":"outside-write",
                  "app-import":"application-import","sql-import":"sql-import"}
        if label not in expected or self.active_control is not None or label in self.controls:refuse("control identity differs")
        before=len(self.denied);self.active_control=label
        try:
            try:
                if label=="socket":socket.socket()
                elif label=="dns":socket.getaddrinfo("synthetic.invalid",443)
                elif label=="process":
                    import subprocess
                    subprocess.Popen([sys.executable,"-c","raise RuntimeError('must not execute')"])
                elif label=="env":os.putenv("PROTOCOL_PRIVACY_FORBIDDEN","synthetic")
                elif label=="secret-file":(Path.cwd()/".env").read_bytes()
                elif label=="outside-write":(SERVER/"tests/protocol_privacy_forbidden.txt").write_text("must not write")
                elif label=="app-import":__import__("app.main")
                elif label=="sql-import":__import__("asyncpg")
            except BoundaryDenied:pass
            else:refuse("forbidden control action was not denied")
        finally:self.active_control=None
        observed=self.denied[before:]
        if observed!=[{"event":expected[label],"control":label}]:refuse("exact controlled denial differs")
        self.controls[label]=True


def no_domain_modules():
    return not any((m=="app" or m.startswith("app.")) and m not in OfflineBoundary.APP_MODULES
                   or m.split(".")[0] in OfflineBoundary.SQL_MODULES for m in sys.modules)


def main():
    try:roots,installed=verify_approval()
    except Exception:
        print(json.dumps({"ok":False,"phase":"offline-source-environment-approval"}));return 2
    empty,scratch,upload,evidence=roots
    anchors={p:(p.stat().st_dev,p.stat().st_ino,p.stat().st_uid) for p in roots}
    boundary=OfflineBoundary((scratch,upload,evidence))
    sys.path[:0]=[str(SITE),str(SERVER)]
    boundary.install()
    signal.signal(signal.SIGALRM,lambda *_:refuse("offline execution time cap"));signal.alarm(MAX_SECONDS)
    import pytest
    from _pytest.subtests import SubtestReport
    saved_filters={n:list(logging.getLogger(n).filters) for n in ("uvicorn.access","gunicorn.access","uvicorn.error")}
    class Evidence:
        def __init__(self):self.collected=[];self.results=[];self.started=[];self.subtests=[]
        def pytest_configure(self,config):config._protocol_privacy_boundary=boundary
        def pytest_collection_modifyitems(self,session,config,items):
            groups={}
            for i in items:
                key=i.nodeid.split("[",1)[0];groups[key]=groups.get(key,0)+1
            ids=[i.nodeid for i in items]
            if (groups!=EXPECTED_GROUP_COUNTS or len(ids)!=EXPECTED_CASES or len(set(ids))!=len(ids)
                    or set(ids)!=set(EXPECTED_FULL_IDS)):raise pytest.UsageError("exact frozen offline cases required")
            self.collected=ids
        def pytest_runtest_setup(self,item):self.started.append(item.nodeid)
        def pytest_runtest_logreport(self,report):
            record={"nodeid":report.nodeid,"when":report.when,"outcome":report.outcome}
            if type(report) is SubtestReport:self.subtests.append(record)
            else:self.results.append(record)
        def pytest_runtest_teardown(self,item,nextitem):
            for p,a in anchors.items():scratch_bound(p,a)
        def pytest_sessionfinish(self,session,exitstatus):
            calls=[r for r in self.results if r["when"]=="call"]
            source_after=sources_unchanged();domain_zero=no_domain_modules()
            expected_controls={"socket","dns","process","env","secret-file","outside-write","app-import","sql-import"}
            uncontrolled=[r for r in boundary.denied if r["control"] is None]
            passed=(not uncontrolled and len(boundary.denied)==8 and set(boundary.controls)==expected_controls
                    and all(boundary.controls.values()) and boundary.probes_restored and source_after and domain_zero
                    and inventory()==installed and len(calls)==EXPECTED_CASES and len(self.started)==EXPECTED_CASES
                    and {r["nodeid"] for r in calls}==set(EXPECTED_FULL_IDS) and len({r["nodeid"] for r in calls})==len(calls)
                    and len(self.results)==3*EXPECTED_CASES and all(r["outcome"]=="passed" for r in self.results) and not self.subtests)
            if not passed:session.exitstatus=1
            payload={"accepted":passed,"results":self.results,"subtests":self.subtests,"collected":self.collected,
                "expected_cases":EXPECTED_CASES,"source_after":source_after,"inventory_count":len(installed),
                "controlled_denials":boundary.denied,"denial_controls":boundary.controls,"uncontrolled_denials":uncontrolled,
                "no_domain_or_sql_modules":domain_zero,"ipv6_import_flag_restored":boundary.probes_restored,
                "sql_operations":0,"network_operations_allowed":0,"servers_started":0,"wire_cases_selected":0,"new_cases":314,"legacy_cases":146,
                "legacy_unchanged_expectations":145,"legacy_intentional_updated":1,
                "frontend_sha256":FRONTEND_SHA256,
                "runner_sha256":os.environ["CAPABILITY_PRIVACY_RUNNER_SHA256"],"app_sha256":APP_DIGEST,
                "tests_without_runner_sha256":TESTS_DIGEST,"schema_sha256":SCHEMA_DIGEST,"exitstatus":int(session.exitstatus)}
            raw=(json.dumps(payload,ensure_ascii=False,indent=2)+"\n").encode()
            if len(raw)>1024*1024:refuse("evidence cap")
            with (evidence/"capability-privacy-boundary.json").open("xb") as output:output.write(raw)
    try:
        return pytest.main(["--noconftest","-c",str(SERVER/"pytest.ini"),"-p","pytest_asyncio.plugin","-p","no:cacheprovider",
            "-vv","--tb=short","--capture=sys","--basetemp="+str(scratch/"pytest-test"),
            "--log-file="+str(evidence/"pytest.log"),"--junitxml="+str(evidence/"capability-privacy.xml"),
            *(str(SERVER/p) for p in SELECTION)],plugins=[Evidence()])
    finally:
        signal.alarm(0)
        for n,filters in saved_filters.items():logging.getLogger(n).filters=filters
        for p,a in anchors.items():scratch_bound(p,a)


if __name__=="__main__":raise SystemExit(main())
